### Ran Playwright code
```js
await (async (page) => {
    const results = [];
    for (let i = 0; i < 10; i++) {
        await page.reload({ waitUntil: 'domcontentloaded' });
        // Wait a bit for content
        await page.waitForTimeout(1000);
        // Extract author lines
        const authorLines = await page.evaluate(() => {
            const entries = document.querySelectorAll('.gs_a');
            if (entries.length) {
                return Array.from(entries).map(el => el.innerText.trim());
            }
            // Fallback
            const allDivs = document.querySelectorAll('div');
            let lines = [];
            for (let div of allDivs) {
                const text = div.innerText.trim();
                if (text.includes(' - ') && text.match(/20\d\d/)) {
                    lines.push(text);
                }
            }
            return lines;
        });
        results.push(authorLines);
        // Wait a bit between reloads
        await page.waitForTimeout(500);
    }
    return results;
})(page);
```

